import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
/** The sentence for an error answer from our endpoints. */
export function errorText(error) {
  const code = error?.response?.errors?.[0]?.code;
  const key = `ernestdefoe-member-map.forum.errors.${code}`;
  return code && app.translator.trans(key) !== key ? extractText(app.translator.trans(key)) : extractText(app.translator.trans('ernestdefoe-member-map.forum.page.load_error'));
}
export function call(method, path, data) {
  const url = app.forum.attribute('apiUrl') + '/member-map' + path;
  return app.request({
    method,
    url: method === 'GET' && data ? url + '?' + new URLSearchParams(data).toString() : url,
    body: method === 'GET' ? undefined : data,
    errorHandler: error => {
      app.alerts.show({
        type: 'error'
      }, errorText(error));
      throw error;
    }
  });
}

/** After saving or removing: the session user's own copy, so profile, card and settings update without a reload. */
export function remember(me) {
  const user = app.session.user;
  if (!user) return;
  user.pushAttributes({
    memberMapOwn: me,
    memberMapLocation: me && me.profile && app.forum.attribute('memberMapProfile') ? me.label : null
  });
}
export function openLocationForm(attrs = {}) {
  app.modal.show(() => import(/* webpackChunkName: 'forum/components/LocationModal', webpackMode: 'lazy-once' */ './components/LocationModal'), attrs);
}
export function removeLocation() {
  return call('DELETE', '/location').then(() => {
    remember(null);
    app.alerts.show({
      type: 'success'
    }, app.translator.trans('ernestdefoe-member-map.forum.location.removed'));
  });
}flarum.reg.addChunkModule('400', '424', 'ernestdefoe-member-map', 'forum/components/LocationModal');